class _EmbeddedLoader(importlib.abc.Loader):
    """Compile and execute one embedded module."""

    def create_module(self, spec: importlib.machinery.ModuleSpec) -> types.ModuleType:
        module = types.ModuleType(spec.name)
        module.__loader__ = self
        module.__spec__ = spec
        module.__file__ = spec.origin
        if spec.submodule_search_locations is not None:
            module.__path__ = list(spec.submodule_search_locations)
        return module

    def exec_module(self, module: types.ModuleType) -> None:
        name = module.__name__
        try:
            source = _MODULES[name]
        except KeyError:  # pragma: no cover - the finder filters first
            raise ImportError(f"embedded build has no module {name!r}") from None
        code = compile(source, f"<embedded:{name}>", "exec")
        exec(code, module.__dict__)


class _EmbeddedFinder(importlib.abc.MetaPathFinder):
    """Serve modules from ``_MODULES`` before the filesystem is consulted."""

    def find_spec(
        self,
        fullname: str,
        path: Any = None,
        target: types.ModuleType | None = None,
    ) -> importlib.machinery.ModuleSpec | None:
        if fullname not in _MODULES:
            return None
        is_package = fullname in _PACKAGES
        spec = importlib.machinery.ModuleSpec(
            fullname,
            _EmbeddedLoader(),
            origin=f"<embedded:{fullname}>",
            is_package=is_package,
        )
        if is_package:
            spec.submodule_search_locations = []  # nothing to discover on disk
        return spec


