    import pathlib

    beside_me = pathlib.Path(__file__).resolve().parent / "src"
    candidates = [beside_me, *[pathlib.Path(entry) for entry in _RUNTIME_FALLBACKS]]
    for candidate in candidates:
        if (candidate / "severitas").is_dir():
            text = str(candidate)
            if text not in sys.path:
                sys.path.append(text)


